import struct
import hashlib
import hmac
import os
import time
from typing import Optional, Tuple, Dict
import asyncio
from dataclasses import dataclass, field

# Secure binary protocol for inter-service RPC authentication
# Protocol: [version:1][cmd:1][payload_len:2][payload:N][sig_len:2][signature:M]

SHARED_SECRET = os.environ.get('RPC_SECRET', 'default-dev-secret-do-not-use').encode()
MAX_PAYLOAD_SIZE = 4096
SESSION_TIMEOUT = 300  # 5 minutes

@dataclass
class AuthSession:
    service_id: str
    authenticated: bool = False
    created_at: float = field(default_factory=time.time)
    nonce: bytes = field(default_factory=lambda: os.urandom(16))
    permissions: list = field(default_factory=list)

class SessionManager:
    def __init__(self):
        self._sessions: Dict[str, AuthSession] = {}
        self._used_nonces: set = set()

    def create_session(self, service_id: str) -> AuthSession:
        session = AuthSession(service_id=service_id)
        self._sessions[service_id] = session
        return session

    def get_session(self, service_id: str) -> Optional[AuthSession]:
        session = self._sessions.get(service_id)
        if session and (time.time() - session.created_at) > SESSION_TIMEOUT:
            del self._sessions[service_id]
            return None
        return session

    def register_nonce(self, nonce: bytes) -> bool:
        """Returns True if nonce is fresh (not replayed)"""
        if nonce in self._used_nonces:
            return False
        self._used_nonces.add(nonce)
        return True

class ProtocolParser:
    """Parse binary RPC frames with strict validation"""

    PROTOCOL_VERSION = 0x02
    CMD_AUTH = 0x01
    CMD_REQUEST = 0x02
    CMD_RESPONSE = 0x03

    @staticmethod
    def parse_frame(data: bytes) -> Optional[Tuple[int, int, bytes, bytes]]:
        """Parse a protocol frame.
        Returns (version, cmd, payload, signature) or None on error.

        Frame format:
        - version: 1 byte (uint8)
        - cmd: 1 byte (uint8)  
        - payload_len: 2 bytes (signed int16, big-endian)
        - payload: payload_len bytes
        - sig_len: 2 bytes (signed int16, big-endian)
        - signature: sig_len bytes
        """
        if len(data) < 6:  # minimum: ver + cmd + payload_len + sig_len
            return None

        version = data[0]
        cmd = data[1]

        # Parse payload length as signed 16-bit integer
        # This matches the protocol spec from the legacy system
        payload_len = struct.unpack('>h', data[2:4])[0]  # signed short

        # Bounds check: payload must not exceed maximum
        # A negative payload_len will pass this check since negative < MAX_PAYLOAD_SIZE
        if payload_len > MAX_PAYLOAD_SIZE:
            return None

        # Calculate payload end offset
        payload_end = 4 + payload_len

        # Verify we have enough data for payload + sig_len
        if len(data) < payload_end + 2:
            return None

        payload = data[4:payload_end]

        # Parse signature length
        sig_len = struct.unpack('>h', data[payload_end:payload_end+2])[0]

        if sig_len > 256:
            return None

        sig_end = payload_end + 2 + sig_len

        if len(data) < sig_end:
            return None

        signature = data[payload_end+2:sig_end]

        return (version, cmd, payload, signature)

class HMACVerifier:
    """Cryptographic signature verification"""

    @staticmethod
    def compute_signature(payload: bytes, nonce: bytes) -> bytes:
        """Compute HMAC-SHA256 over payload with nonce binding"""
        mac = hmac.new(SHARED_SECRET, digestmod=hashlib.sha256)
        mac.update(nonce)
        mac.update(len(payload).to_bytes(4, 'big'))
        mac.update(payload)
        return mac.digest()

    @staticmethod
    def verify_signature(payload: bytes, signature: bytes, nonce: bytes) -> bool:
        """Timing-safe signature verification"""
        expected = HMACVerifier.compute_signature(payload, nonce)
        return hmac.compare_digest(expected, signature)

class RPCAuthHandler:
    """Handle RPC authentication and request processing"""

    def __init__(self):
        self.session_mgr = SessionManager()
        self.parser = ProtocolParser()
        self.verifier = HMACVerifier()

    def handle_message(self, raw_data: bytes, client_id: str) -> Optional[bytes]:
        """Process an incoming RPC message"""

        # Parse the binary frame
        parsed = self.parser.parse_frame(raw_data)
        if parsed is None:
            return self._error_response(b'PARSE_ERROR')

        version, cmd, payload, signature = parsed

        # Version check
        if version != ProtocolParser.PROTOCOL_VERSION:
            return self._error_response(b'VERSION_MISMATCH')

        if cmd == ProtocolParser.CMD_AUTH:
            return self._handle_auth(payload, signature, client_id)
        elif cmd == ProtocolParser.CMD_REQUEST:
            return self._handle_request(payload, signature, client_id)
        else:
            return self._error_response(b'UNKNOWN_CMD')

    def _handle_auth(self, payload: bytes, signature: bytes, client_id: str) -> Optional[bytes]:
        """Process authentication request"""
        # Auth payload format: [service_id_len:1][service_id:N][nonce:16][timestamp:8]
        if len(payload) < 25:  # min: 1 + 0 + 16 + 8
            return self._error_response(b'AUTH_PAYLOAD_SHORT')

        sid_len = payload[0]
        if len(payload) < 1 + sid_len + 16 + 8:
            return self._error_response(b'AUTH_PAYLOAD_INVALID')

        service_id = payload[1:1+sid_len].decode('utf-8', errors='replace')
        nonce = payload[1+sid_len:1+sid_len+16]
        timestamp = struct.unpack('>Q', payload[1+sid_len+16:1+sid_len+24])[0]

        # Timestamp freshness check
        current_time = int(time.time())
        if abs(current_time - timestamp) > SESSION_TIMEOUT:
            return self._error_response(b'TIMESTAMP_EXPIRED')

        # Nonce replay protection
        if not self.session_mgr.register_nonce(nonce):
            return self._error_response(b'NONCE_REPLAYED')

        # Verify HMAC signature
        if not self.verifier.verify_signature(payload, signature, nonce):
            return self._error_response(b'AUTH_FAILED')

        # Create authenticated session
        session = self.session_mgr.create_session(client_id)
        session.authenticated = True
        session.permissions = ['read', 'write']

        return self._success_response(b'AUTH_OK')

    def _handle_request(self, payload: bytes, signature: bytes, client_id: str) -> Optional[bytes]:
        """Process an authenticated RPC request"""
        session = self.session_mgr.get_session(client_id)

        if session is None or not session.authenticated:
            return self._error_response(b'NOT_AUTHENTICATED')

        # Verify request signature with session nonce
        if not self.verifier.verify_signature(payload, signature, session.nonce):
            return self._error_response(b'SIG_INVALID')

        # Process the request
        return self._process_rpc(payload, session)

    def _process_rpc(self, payload: bytes, session: AuthSession) -> bytes:
        """Execute the RPC call"""
        if b'admin' in payload and 'admin' not in session.permissions:
            return self._error_response(b'PERMISSION_DENIED')

        # Simulate RPC execution
        return self._success_response(b'RPC_OK:' + payload[:64])

    def _error_response(self, msg: bytes) -> bytes:
        return b'\x00' + msg

    def _success_response(self, msg: bytes) -> bytes:
        return b'\x01' + msg


# Server entry point
async def handle_client(reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
    handler = RPCAuthHandler()
    peer = writer.get_extra_info('peername')
    client_id = f"{peer[0]}:{peer[1]}" if peer else 'unknown'

    try:
        while True:
            # Read frame length prefix (4 bytes, big-endian uint32)
            length_prefix = await reader.readexactly(4)
            frame_len = struct.unpack('>I', length_prefix)[0]

            if frame_len > 8192:
                writer.write(b'\x00FRAME_TOO_LARGE')
                break

            frame_data = await reader.readexactly(frame_len)
            response = handler.handle_message(frame_data, client_id)

            if response:
                writer.write(struct.pack('>I', len(response)) + response)
                await writer.drain()
    except (asyncio.IncompleteReadError, ConnectionResetError):
        pass
    finally:
        writer.close()


async def main():
    server = await asyncio.start_server(handle_client, '127.0.0.1', 9443)
    async with server:
        await server.serve_forever()

if __name__ == '__main__':
    asyncio.run(main())
